#include <stdio.h>
#include <stdint.h>

#define MOD 998244353LL

static long long mod_pow(long long a, long long e) {
    long long r = 1 % MOD;
    a %= MOD;
    while (e > 0) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    long long N, M, K;
    if (scanf("%lld %lld %lld", &N, &M, &K) != 3) return 0;

    if (N == 1) {
        printf("%lld\n", M % MOD);
        return 0;
    }

    long long maxSame = N - 1;
    if (K > maxSame) K = maxSame;

    /* We count colorings with exactly x adjacent equal pairs:
       choose which x of the N-1 edges are equal, then:
       first block: M choices
       each unequal edge: M-1 choices
       each equal edge: 1 choice
       => count = M * C(N-1, x) * (M-1)^(N-1-x)
       Answer = sum for x = 0..K
    */

    long long n = N - 1;

    long long *fact = (long long *)malloc((n + 1) * sizeof(long long));
    long long *invfact = (long long *)malloc((n + 1) * sizeof(long long));
    if (!fact || !invfact) return 0;

    fact[0] = 1;
    for (long long i = 1; i <= n; i++) fact[i] = (fact[i - 1] * i) % MOD;

    invfact[n] = mod_pow(fact[n], MOD - 2);
    for (long long i = n; i >= 1; i--) invfact[i - 1] = (invfact[i] * i) % MOD;

    long long ans = 0;
    for (long long x = 0; x <= K; x++) {
        long long comb = fact[n];
        comb = (comb * invfact[x]) % MOD;
        comb = (comb * invfact[n - x]) % MOD;

        long long ways = M % MOD;
        ways = (ways * comb) % MOD;
        ways = (ways * mod_pow((M - 1 + MOD) % MOD, n - x)) % MOD;

        ans += ways;
        if (ans >= MOD) ans -= MOD;
    }

    printf("%lld\n", ans % MOD);

    free(fact);
    free(invfact);
    return 0;
}

