static const long long MOD = 998244353;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N, M, K;
    cin >> N >> M >> K;

    // Let x be the number of adjacent equal pairs.
    // We need sum over x = 0..K of:
    //   M * C(N-1, x) * (M-1)^(N-1-x)
    //
    // Reason:
    // Choose which x of the N-1 adjacent positions are "equal".
    // The first block has M choices.
    // For each "equal" edge, next block is forced.
    // For each "different" edge, next block has (M-1) choices.

    long long ans = 0;

    // Precompute factorials and inverse factorials up to N-1
    vector<long long> fact(N), invfact(N);
    fact[0] = 1;
    for (int i = 1; i <= N - 1; ++i) fact[i] = fact[i - 1] * i % MOD;

    auto modpow = [&](long long a, long long e) {
        long long r = 1 % MOD;
        while (e > 0) {
            if (e & 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    };

    invfact[N - 1] = modpow(fact[N - 1], MOD - 2);
    for (int i = (int)N - 2; i >= 0; --i) {
        invfact[i] = invfact[i + 1] * (i + 1) % MOD;
    }

    auto C = [&](long long n, long long r) -> long long {
        if (r < 0 || r > n) return 0;
        return fact[n] * invfact[r] % MOD * invfact[n - r] % MOD;
    };

    long long maxX = min(K, N - 1);
    for (long long x = 0; x <= maxX; ++x) {
        long long ways = C(N - 1, x);
        ways = ways * M % MOD;
        ways = ways * modpow(M - 1, N - 1 - x) % MOD;
        ans += ways;
        if (ans >= MOD) ans -= MOD;
    }

    cout << ans % MOD << '\n';
    return 0;
}

