        fact[0] = 1;
        for (int i = 1; i < N; i++) {
            fact[i] = fact[i-1] * i % MOD;
        }
        invFact[N-1] = modPow(fact[N-1], MOD - 2);
        for (int i = N-2; i >= 0; i--) {
            invFact[i] = invFact[i+1] * (i+1) % MOD;
        }

        long ans = 0;
        long powM1 = modPow(M-1, N-1); // (M-1)^(N-1)
        long invM1 = modPow(M-1, MOD-2);

        for (int i = 0; i <= K && i <= N-1; i++) {
            long comb = fact[N-1] * invFact[i] % MOD * invFact[N-1-i] % MOD;
            long part = comb * M % MOD * powM1 % MOD;
            ans = (ans + part) % MOD;

            // update powM1 for next i (divide by (M-1))
            powM1 = powM1 * invM1 % MOD;
        }

        System.out.println(ans);
    }

    static long modPow(long a, long e) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = res * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return res;
    }
}

