public class Main {
    static final long MOD = 998244353L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        long M = fs.nextLong();
        int K = fs.nextInt();

        // Number of colorings with exactly s equal-adjacent pairs:
        // choose which of the N-1 adjacent positions are equal: C(N-1, s)
        // choose first color: M
        // for each of the remaining N-1 positions:
        //   if equal -> forced
        //   if different -> M-1 choices
        // Hence count = M * C(N-1, s) * (M-1)^(N-1-s)
        // We need sum for s = 0..K

        long[] fact = new long[N];
        long[] invFact = new long[N];
        fact[0] = 1;
        for (int i = 1; i < N; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[N - 1] = modPow(fact[N - 1], MOD - 2);
        for (int i = N - 2; i >= 0; i--) invFact[i] = invFact[i + 1] * (i + 1) % MOD;

        long ans = 0;
        long mMod = M % MOD;
        long base = ((M - 1) % MOD + MOD) % MOD;

        for (int s = 0; s <= K && s <= N - 1; s++) {
            long comb = fact[N - 1] * invFact[s] % MOD * invFact[N - 1 - s] % MOD;
            long ways = mMod * comb % MOD * modPow(base, N - 1 - s) % MOD;
            ans += ways;
            if (ans >= MOD) ans -= MOD;
        }

        System.out.println(ans % MOD);
    }

    static long modPow(long a, long e) {
        long r = 1 % MOD;
        a %= MOD;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
